begin;
alter table public.apostolic_cities add column population integer not null default 40 check(population between 0 and 1000000),add column satisfaction integer not null default 100 check(satisfaction between 0 and 1000),add column population_updated_at timestamptz not null default clock_timestamp();
create table public.apostolic_city_slot_catalog(slot_no smallint primary key check(slot_no between 1 and 12),terrain text not null check(terrain in('land','coast')),unlock_town_hall_level smallint not null check(unlock_town_hall_level between 1 and 100),x smallint not null check(x between 0 and 100),y smallint not null check(y between 0 and 100),unique(x,y));
insert into public.apostolic_city_slot_catalog values(1,'land',1,28,42),(2,'land',1,43,31),(3,'land',1,58,43),(4,'coast',1,76,73),(5,'land',3,37,58),(6,'land',5,52,59),(7,'land',8,67,55),(8,'land',10,22,61),(9,'land',14,48,75),(10,'land',17,63,72),(11,'land',24,76,42),(12,'coast',10,86,66);
alter table public.apostolic_city_buildings add column slot_no smallint references public.apostolic_city_slot_catalog(slot_no);
create unique index apostolic_city_building_slot_idx on public.apostolic_city_buildings(city_id,slot_no)where slot_no is not null;
update public.apostolic_city_buildings set slot_no=case building when'town_hall'then 1 when'warehouse'then 2 when'farm'then 3 when'market'then 4 when'lumberyard'then 5 when'quarry'then 6 when'olive_press'then 7 when'academy'then 8 else null end;
alter table public.apostolic_city_slot_catalog enable row level security;create policy apostolic_city_slot_catalog_read on public.apostolic_city_slot_catalog for select to authenticated using(true);revoke all on public.apostolic_city_slot_catalog from anon,authenticated;grant select on public.apostolic_city_slot_catalog to authenticated;
create or replace function public.apostolic_sync_city_state()returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());cid uuid;elapsed numeric;pop integer;cap integer;sat integer;gold_gain bigint;town_level integer;now_at timestamptz:=clock_timestamp();begin if uid is null then raise exception'authentication required';end if;select c.id,c.population,c.satisfaction,extract(epoch from(now_at-c.population_updated_at))/3600.0,b.level into cid,pop,sat,elapsed,town_level from public.apostolic_cities c join public.apostolic_city_buildings b on b.city_id=c.id and b.building='town_hall'where c.owner_id=uid for update of c;if cid is null then return null;end if;cap:=60+town_level*40;pop:=least(cap,greatest(0,pop+floor(elapsed*greatest(0,sat-50)/25.0)::integer));gold_gain:=greatest(0,floor(elapsed*pop*.25)::bigint);update public.apostolic_cities set population=pop,population_updated_at=now_at,updated_at=now_at where id=cid;update public.apostolic_city_resources set amount=least(capacity,amount+gold_gain),last_collected_at=now_at,updated_at=now_at where city_id=cid and resource='gold';return public.apostolic_get_city_overview();end;$$;
create or replace function public.apostolic_get_city_management()returns jsonb language sql stable security definer set search_path=''as $$with own as(select c.*,b.level town_level from public.apostolic_cities c join public.apostolic_city_buildings b on b.city_id=c.id and b.building='town_hall'where c.owner_id=(select auth.uid()))select coalesce((select jsonb_build_object('city',jsonb_build_object('id',o.id,'name',o.name,'town_hall_level',o.town_level,'population',o.population,'capacity',60+o.town_level*40,'satisfaction',o.satisfaction,'visual_phase',case when o.town_level<=3 then 1 when o.town_level<=9 then 2 when o.town_level<=15 then 3 when o.town_level<=24 then 4 else 5 end),'gold',(select jsonb_build_object('amount',amount,'per_hour',production_per_hour+floor(o.population*.25))from public.apostolic_city_resources where city_id=o.id and resource='gold'),'slots',(select jsonb_agg(jsonb_build_object('slot',s.slot_no,'terrain',s.terrain,'x',s.x,'y',s.y,'unlock_level',s.unlock_town_hall_level,'unlocked',o.town_level>=s.unlock_town_hall_level,'building',b.building,'building_level',b.level,'state',b.state)order by s.slot_no)from public.apostolic_city_slot_catalog s left join public.apostolic_city_buildings b on b.city_id=o.id and b.slot_no=s.slot_no),'queue',(select to_jsonb(q)from(select building,to_level,finishes_at from public.apostolic_construction_queue where city_id=o.id and status='building'limit 1)q))from own o),'null'::jsonb)$$;
revoke all on function public.apostolic_sync_city_state(),public.apostolic_get_city_management()from public;grant execute on function public.apostolic_sync_city_state(),public.apostolic_get_city_management()to authenticated;
commit;
